 * the end of the format's loan period, or the branch's next open day after it when the branch is
 * closed that day, on a closed weekday or a holiday.
 */
export function computeDueDate({ checkedOutOn, format, branch }) {
  return nextOpenDay(branch, addDays(checkedOutOn, LOAN_RULES[format].loanDays));
}

