/**
 * Tells whether a branch is open on a calendar date: not on a closed weekday, not on a holiday,
 * not within a closure (a branch without closures has no `closures` field; both ends are included).
 */
export function isOpenOn(branch, isoDate) {
  if (branch.closedWeekdays.includes(weekdayOf(isoDate)) || branch.holidays.includes(isoDate)) return false;
  return !(branch.closures ?? []).some((closure) => closure.from <= isoDate && isoDate <= closure.to);
}

