  assert.equal(isOpenOn(renovated, '2027-01-31'), true);
  assert.equal(isOpenOn(renovated, '2027-02-01'), false);
  assert.equal(isOpenOn(renovated, '2027-02-10'), false);
  assert.equal(isOpenOn(renovated, '2027-02-14'), false);
  assert.equal(isOpenOn(renovated, '2027-02-15'), false); // a Monday, but see below
});

test('the next open day of a day within a closure is the first open day after it', () => {
  assert.equal(nextOpenDay(renovated, '2027-02-01'), '2027-02-15');
  assert.equal(nextOpenDay(renovated, '2027-02-14'), '2027-02-15');
  assert.equal(nextOpenDay(renovated, '2027-01-31'), '2027-02-15');
});

test('a branch with several closures is closed in each of them', () => {
  const branch = {
    ...branchById('hillcrest'),
    closures: [RENOVATION, { from: '2027-02-15', to: '2027-02-16' }],
  };
  assert.equal(nextOpenDay(branch, '2027-02-02'), '2027-02-17');
});
